Fixpoint ndig_f (fuel : nat) (x : Z) : Z :=
  match fuel with
  | O => 1
  | S f => if x <? 10 then 1 else 1 + ndig_f f (x / 10)
  end.
Definition ndig (x : Z) : Z := ndig_f 20 x.

Arguments ndig _ : simpl never.

